-- ────────────────────────────────────────────────────────────────────
-- category_product — deliberadamente VACÍA
-- ────────────────────────────────────────────────────────────────────
-- Ninguno de los 1200 productos del mock trae la relación con
-- categorías poblada, aunque la entidad la declara y el buscador filtra por
-- `categories.slug`. Es decir: hoy, en la app original, cualquier búsqueda
-- por categoría devuelve cero resultados.
--
-- No se inventan enlaces aquí. Este hueco es precisamente lo que los
-- productos del scraper sí podrán rellenar, porque ellos sí traen categoría.

-- ────────────────────────────────────────────────────────────────────
-- Secuencias
-- ────────────────────────────────────────────────────────────────────
-- Los ids se insertaron explícitamente para preservar las relaciones del
-- mock, así que hay que adelantar las secuencias o el primer INSERT nuevo
-- chocaría con una clave existente.
SELECT setval('types_id_seq', GREATEST((SELECT COALESCE(max(id), 1) FROM types), 1));
SELECT setval('shops_id_seq', GREATEST((SELECT COALESCE(max(id), 1) FROM shops), 1));
SELECT setval('categories_id_seq', GREATEST((SELECT COALESCE(max(id), 1) FROM categories), 1));
SELECT setval('manufacturers_id_seq', GREATEST((SELECT COALESCE(max(id), 1) FROM manufacturers), 1));
SELECT setval('tags_id_seq', GREATEST((SELECT COALESCE(max(id), 1) FROM tags), 1));
SELECT setval('products_id_seq', GREATEST((SELECT COALESCE(max(id), 1) FROM products), 1));

COMMIT;
